def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in '+-*/':
            if len(stack) < 2:
                raise ValueError('Invalid expression')
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))
        else:
            raise ValueError('Invalid token')
    if len(stack) != 1:
        raise ValueError('Invalid expression')
    return stack[0]
